{
  "name": "pl_stage_and_merge",
  "properties": {
    "description": "Load a staging table, merge it into silver, then drop the staging table.",
    "activities": [
      {
        "name": "Load staging",
        "type": "Copy",
        "dependsOn": [],
        "policy": {
          "timeout": "0.12:00:00",
          "retry": 0,
          "retryIntervalInSeconds": 30,
          "secureOutput": false,
          "secureInput": false
        },
        "outputs": [
          {
            "referenceName": "ds_staging_orders",
            "type": "DatasetReference"
          }
        ],
        "typeProperties": {
          "source": {
            "type": "AzureSqlSource",
            "sqlReaderQuery": "SELECT * FROM source.orders",
            "queryTimeout": "02:00:00",
            "partitionOption": "None"
          },
          "sink": {
            "type": "AzureSqlSink",
            "writeBehavior": "insert",
            "sqlWriterUseTableLock": false,
            "tableOption": "autoCreate"
          },
          "enableStaging": false
        }
      },
      {
        "name": "Merge into target",
        "type": "Script",
        "dependsOn": [
          {
            "activity": "Load staging",
            "dependencyConditions": [
              "Succeeded"
            ]
          }
        ],
        "policy": {
          "timeout": "0.12:00:00",
          "retry": 0,
          "retryIntervalInSeconds": 30,
          "secureOutput": false,
          "secureInput": false
        },
        "linkedServiceName": {
          "referenceName": "ls_lab_sql",
          "type": "LinkedServiceReference"
        },
        "typeProperties": {
          "scripts": [
            {
              "type": "NonQuery",
              "text": "MERGE INTO silver.orders AS t USING staging.orders AS s ON t.order_id = s.order_id WHEN MATCHED THEN UPDATE SET net_amount = s.net_amount WHEN NOT MATCHED THEN INSERT (order_id, net_amount) VALUES (s.order_id, s.net_amount);"
            }
          ],
          "scriptBlockExecutionTimeout": "02:00:00"
        }
      },
      {
        "name": "Drop staging",
        "type": "Script",
        "dependsOn": [
          {
            "activity": "Merge into target",
            "dependencyConditions": [
              "Completed",
              "Skipped"
            ]
          }
        ],
        "policy": {
          "timeout": "0.12:00:00",
          "retry": 0,
          "retryIntervalInSeconds": 30,
          "secureOutput": false,
          "secureInput": false
        },
        "linkedServiceName": {
          "referenceName": "ls_lab_sql",
          "type": "LinkedServiceReference"
        },
        "typeProperties": {
          "scripts": [
            {
              "type": "NonQuery",
              "text": "DROP TABLE IF EXISTS staging.orders;"
            }
          ],
          "scriptBlockExecutionTimeout": "02:00:00"
        }
      }
    ],
    "annotations": []
  }
}

